from collections import deque, Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    singletons = []
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            q = [(r, c)]
            seen.add((r, c))
            for y, x in q:
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx)); q.append((ny,nx))
            if len(q) == 1:
                singletons.append((r,c))
    out = [row[:] for row in grid]
    for r,c in singletons:
        counts = Counter(grid[y][x] for y in range(max(0,r-1),min(h,r+2))
                         for x in range(max(0,c-1),min(w,c+2)) if (y,x)!=(r,c))
        if not counts:
            continue
        best = max(counts.values())
        choices = [color for color,n in counts.items() if n == best]
        # Restore a missing cell when its three 2x2 neighbors agree, even if
        # the broader neighborhood has a different majority.
        square_scores = Counter()
        for y0 in (r-1,r):
            for x0 in (c-1,c):
                cells = [(y,x) for y in (y0,y0+1) for x in (x0,x0+1)
                         if 0 <= y < h and 0 <= x < w and (y,x)!=(r,c)]
                if len(cells) == 3:
                    colors = [grid[y][x] for y,x in cells]
                    if colors.count(colors[0]) == 3:
                        square_scores[colors[0]] += 1
        if square_scores:
            out[r][c] = square_scores.most_common(1)[0][0]
        else:
            out[r][c] = choices[0]
    return out

